// ==== EDIT THESE LISTS ====
const BLOCKED_SENDERS = ["billing@lu.ma", "receipts@lu.ma"]; // senders/domains to exclude
const SENSITIVE_KEYWORDS = ["payment", "invoice", "receipt", "personal", "password", "ssn", "bank", "confidential", "private"];
const SENSITIVE_LABELS = ["CONFIDENTIAL", "PRIVATE", "IMPORTANT_PRIVATE"];
// ==========================

const items = $input.all();
const kept = [];
let skipped = 0;

for (const i of items) {
  const j = i.json;
  const from = (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || (typeof j.from === "string" ? j.from : "") || "unknown";
  const subject = j.subject || "(no subject)";
  const snippet = j.snippet || "";
  const labels = j.labelIds || j.labels || [];
  const attachments = j.attachments || (j.attachment ? [j.attachment] : []);
  const haystack = (subject + " " + snippet).toLowerCase();

  const senderBlocked = BLOCKED_SENDERS.some(s => from.toLowerCase().includes(s.toLowerCase()));
  const keywordHit = SENSITIVE_KEYWORDS.some(k => haystack.includes(k.toLowerCase()));
  const labelHit = Array.isArray(labels) && labels.some(l => SENSITIVE_LABELS.includes(String(l).toUpperCase()));
  const hasAttachment = Array.isArray(attachments) && attachments.length > 0;

  if (senderBlocked || keywordHit || labelHit || hasAttachment) {
    skipped++;
    continue; // skipped entirely: never reaches AI or Slack
  }

  kept.push({ subject, from, snippet, date: j.date || j.internalDate || "" });
}

const text = kept.map((e, idx) => (idx + 1) + ". " + e.subject + " — " + e.snippet).join("\n");
return [{ json: { count: kept.length, skipped, emails: kept, text } }];

